const allItems = $input.all();
const cfg = $('⚙️ Configuración').first().json;
const map = {};
for (const item of allItems) {
  const { id, especialidad } = item.json;
  if (!especialidad || !id) continue;
  const idInt = parseInt(id);
  const nombre = especialidad.trim();
  map[nombre] = idInt;
  map[nombre.toLowerCase()] = idInt;
  const sinAcentos = nombre.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  map[sinAcentos] = idInt;
}
const aliases = {
  'Odontologia General': 'Odontología General',
  'Cirugia': 'Cirugía',
  'Implantes': 'Implantología',
  'Articulo': 'Artículos y Materiales',
  'Artículo': 'Artículos y Materiales',
  'Diagnostico': 'Diagnóstico',
  'Rehabilitacion Oral': 'Rehabilitación Oral',
  'Odontopediatria': 'Odontopediatría',
  'Implantologia': 'Implantología',
};
for (const [alias, canonical] of Object.entries(aliases)) {
  const canonicalId = map[canonical] || map[canonical.toLowerCase()];
  if (canonicalId !== undefined) { map[alias] = canonicalId; map[alias.toLowerCase()] = canonicalId; }
}
const defaultId = map['Odontología General'] || 1;

// Construir la URL del CSV desde el ID del Google Sheet
const sheetId = cfg.google_sheet_id || '1VAFtGLJ7nAl0uBQwOCzgjjTMvNkaLAY0';
const csvUrl = `https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv`;

return [{ json: { specialtyMap: map, defaultSpecialtyId: defaultId, practica_id: cfg.practica_id, csv_url: csvUrl, duracion: cfg.duracion_default, meses: cfg.meses_default, iva: cfg.iva_default, google_sheet_id: sheetId } }];

const httpData = $input.first().json;
const csvText = httpData.data || httpData.body || '';
const mapNode = $('🗺️ Construir Mapa Especialidades').first().json;
const specialtyMap = mapNode.specialtyMap;
const defaultId = mapNode.defaultSpecialtyId;
const practica_id = mapNode.practica_id;
function parseCSVLine(line) {
  const result = []; let current = ''; let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') { if (inQuotes && line[i+1] === '"') { current += '"'; i++; } else inQuotes = !inQuotes; }
    else if (ch === ',' && !inQuotes) { result.push(current.trim()); current = ''; }
    else current += ch;
  }
  result.push(current.trim()); return result;
}
function parsePrice(raw) { if (!raw) return 0; const cleaned = raw.replace(/[^0-9.]/g, ''); return parseFloat(cleaned) || 0; }
const lines = csvText.split(/\r?\n/);
const rawHeaders = parseCSVLine(lines[4]);
const headers = rawHeaders.map(h => h.trim());
const iEspecialidad = headers.findIndex(h => h.toLowerCase().includes('especialidad'));
const iDescripcion = headers.findIndex(h => h.toLowerCase().includes('descripci'));
const iPrecioEfec = headers.findIndex(h => h.toLowerCase().includes('precio efectivo'));
const items = [];
for (let i = 5; i < lines.length; i++) {
  const line = lines[i]; if (!line || !line.trim()) continue;
  const values = parseCSVLine(line);
  const nombreServicio = (values[iDescripcion] || '').trim();
  const unit_price = parsePrice(values[iPrecioEfec]);
  if (!nombreServicio || unit_price <= 0) continue;
  const espNombre = iEspecialidad >= 0 ? (values[iEspecialidad] || '').trim() : '';
  const especialidadId = specialtyMap[espNombre] || specialtyMap[espNombre.toLowerCase()] || defaultId;
  items.push({ json: { name: nombreServicio, unit_price, duracion: mapNode.duracion, especialidad: especialidadId, meses: mapNode.meses, costo: unit_price, iva: mapNode.iva, descuento_efectivo: 0, practica_id, eliminado: 0 } });
}

console.log(`[SYNC] Google Sheet ${mapNode.google_sheet_id}: ${items.length} servicios encontrados`);
return items;

